  const form = document.getElementById('contact-form');
  const fullName = document.getElementById('fullName');
  const email = document.getElementById('email');
  const phone = document.getElementById('phone');
  const successEl = document.getElementById('form-success');

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  // Optional leading +, then 7-15 digits, allowing spaces/dashes/parentheses as separators.
  const phoneRegex = /^\+?[0-9][0-9\s\-().]{6,20}$/;

  function setError(input, message) {
    const field = input.closest('.form-field');
    const errorEl = document.getElementById(input.id + '-error');
    if (message) {
      field.classList.add('invalid');
      errorEl.textContent = message;
      input.setAttribute('aria-invalid', 'true');
    } else {
      field.classList.remove('invalid');
      errorEl.textContent = '';
      input.removeAttribute('aria-invalid');
    }
  }

  function validateFullName() {
    const value = fullName.value.trim();
    if (!value) {
      setError(fullName, 'Please enter your full name.');
      return false;
    }
    if (value.length < 2) {
      setError(fullName, 'Name must be at least 2 characters.');
      return false;
    }
    setError(fullName, '');
    return true;
  }

  function validateEmail() {
    const value = email.value.trim();
    if (!value) {
      setError(email, 'Please enter your email address.');
      return false;
    }
    if (!emailRegex.test(value)) {
      setError(email, 'Please enter a valid email address.');
      return false;
    }
    setError(email, '');
    return true;
  }

  function validatePhone() {
    const value = phone.value.trim();
    if (!value) {
      setError(phone, '');
      return true;
    }
    if (!phoneRegex.test(value)) {
      setError(phone, 'Please enter a valid phone number (e.g. +1 555 123 4567).');
      return false;
    }
    const digitCount = value.replace(/\D/g, '').length;
    if (digitCount < 7 || digitCount > 15) {
      setError(phone, 'Phone number must contain between 7 and 15 digits.');
      return false;
    }
    setError(phone, '');
    return true;
  }

  fullName.addEventListener('blur', validateFullName);
  fullName.addEventListener('input', () => {
    if (fullName.closest('.form-field').classList.contains('invalid')) validateFullName();
  });

  email.addEventListener('blur', validateEmail);
  email.addEventListener('input', () => {
    if (email.closest('.form-field').classList.contains('invalid')) validateEmail();
  });

  phone.addEventListener('blur', validatePhone);
  phone.addEventListener('input', () => {
    if (phone.closest('.form-field').classList.contains('invalid')) validatePhone();
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    successEl.textContent = '';

    const okName = validateFullName();
    const okEmail = validateEmail();
    const okPhone = validatePhone();

    if (okName && okEmail && okPhone) {
      successEl.textContent = 'Thanks! Your message has been sent.';
      form.reset();
    } else {
      const firstInvalid = form.querySelector('.form-field.invalid input');
      if (firstInvalid) firstInvalid.focus();
    }
  });
})();
